<title>{{$activity->name}}</title>

<script>
    function initMemoryGame() {
        // Array di immagini per il mazzo di carte
        const deckCards = ["carta-1.png", "carta-1.png", "carta-2.png", "carta-2.png", "carta-3.png", "carta-3.png", "carta-4.png", "carta-4.png", "carta-5.png", "carta-5.png", "carta-6.png", "carta-6.png"];

        // Array globali
        // Accede all'<ul> con la classe .deck
        const deck = document.querySelector(".deck");
        // Crea un array vuoto per memorizzare le carte aperte
        let opened = [];
        // Crea un array vuoto per memorizzare le carte abbinate
        let matched = [];

        const timeStat = document.querySelector('[data-meta-memory-stat="time"]');
        const movesStat = document.querySelector('[data-meta-memory-stat="moves"]');

        // Accede alla modale
        const modal = document.getElementById("modal");

        // Accede al pulsante di reset
        const reset = document.querySelector(".reset-btn");
        // Accede al pulsante "Gioca ancora"
        // const playAgain = document.querySelector(".play-again-btn");

        // Seleziona l'elemento con la classe moves-counter e ne cambia l'HTML
        const movesCount = document.querySelector(".moves-counter");
        // Crea una variabile per il contatore delle mosse, inizia il conteggio da zero
        let moves = 0;

        //seleziona l'elemento con la classe completate-counter
        const matchedCount = document.querySelector(".matched-counter");


        // Accede all'elemento <ul> per la sezione delle stelle e poi agli elementi <li> al suo interno
        //const star = document.getElementById("star-rating").querySelectorAll(".star");
        // Variabile per tenere traccia di quante stelle sono rimaste
        let starCount = 3;

        // Ottiene il tag <span> per il timer.
        const timeCounter = document.querySelector(".timer");
        // Per usare questa variabile per fermare il tempo avviato in timer
        let time;
        // Crea variabili per il conteggio del tempo, inizia tutto da zero
        let minutes = 0;
        let seconds = 0;
        // Per l'uso nell'event listener del click sulla carta
        let timeStart = false;

        // Funzione di mescolamento da http://stackoverflow.com/a/2450976
        function shuffle(array) {
            let currentIndex = array.length, temporaryValue, randomIndex;

            while (currentIndex !== 0) {
                randomIndex = Math.floor(Math.random() * currentIndex);
                currentIndex -= 1;
                temporaryValue = array[currentIndex];
                array[currentIndex] = array[randomIndex];
                array[randomIndex] = temporaryValue;
            }
            return array;
        }

        /*
        Avvia il gioco: mescola il mazzo, crea tag <li> e tag <img>
        e li aggiunge all'<ul> del mazzo con il nuovo contenuto mescolato
        */
        function startGame() {
            // Invoca la funzione di mescolamento e la memorizza in una variabile
            const shuffledDeck = shuffle(deckCards);
            // Itera sull'array del mazzo di carte
            for (let i = 0; i < shuffledDeck.length; i++) {
                // Crea i tag <li>
                const liTag = document.createElement('LI');
                // Assegna all'<li> la classe card
                liTag.classList.add('card');
                // Crea i tag <img>
                const addImage = document.createElement("IMG");
                // Aggiunge <img> a <li>
                liTag.appendChild(addImage);
                // Imposta il percorso src dell'immagine con il mazzo mescolato
                addImage.setAttribute("src", "/img/memory/carte/" + shuffledDeck[i]);
                // Aggiunge un tag alt all'immagine
                addImage.setAttribute("alt", "immagine del vault boy di fallout");
                // Aggiorna il nuovo <li> all'<ul> del mazzo
                deck.appendChild(liTag);
            }
        }

        startGame();

        /*
        Rimuove tutti i nodi figlio dai tag <li> del mazzo e dai
        tag <img>. Da chiamare solo nella funzione resetEverything
        */
        function removeCard() {
            // Finché l'<ul> deck ha un nodo figlio, lo rimuove
            while (deck.hasChildNodes()) {
                deck.removeChild(deck.firstChild);
            }
        }

        /*
        Aggiorna il timer nell'HTML per minuti e secondi
        Questa funzione timer() viene invocata nell'event listener
        al primo click sulla carta
        Usato: https://www.w3schools.com/js/js_timing.asp
        */
        function timer() {
            // Aggiorna il conteggio ogni 1 secondo
            time = setInterval(function() {
                seconds++;
                    if (seconds === 60) {
                        minutes++;
                        seconds = 0;
                    }
                // Format con zero iniziale
                const formattedMinutes = String(minutes).padStart(2, '0');
                const formattedSeconds = String(seconds).padStart(2, '0');

                timeCounter.innerHTML = `${formattedMinutes}:${formattedSeconds}`;
            }, 1000);
        }

        /*
        Ferma il timer una volta che l'utente ha abbinato
        tutte le 16 carte, per un totale di 8 coppie
        Usato: https://www.w3schools.com/js/js_timing.asp
        */
        function stopTime() {
            clearInterval(time);
        }

        /*
        Resetta tutte le variabili globali e il contenuto degli elementi HTML
        timer, stelle, mosse, e l'innerHTML di mosse e timer
        */
        function resetEverything() {
            // Ferma il tempo, resetta i minuti e i secondi, aggiorna l'innerHTML del tempo
            stopTime();
            timeStart = false;
            seconds = 0;
            minutes = 0;
            timeCounter.innerHTML = "00:00";
            // Resetta il conteggio delle stelle e aggiunge nuovamente la classe per mostrare le stelle
            //star[1].firstElementChild.classList.add("fa-star");
            //star[2].firstElementChild.classList.add("fa-star");
            //starCount = 3;
            // Resetta il conteggio delle mosse e resetta il suo innerHTML
            moves = 0;
            movesCount.innerHTML = 0;

            matchedCount.innerHTML = "0 / 6";

            // Pulisce entrambi gli array che contengono le carte aperte e abbinate
            matched = [];
            opened = [];
            // Pulisce il mazzo
            removeCard();
            // Crea un nuovo mazzo
            startGame();
        }

        /*
        Incrementa il contatore delle mosse. Da chiamare ad ogni
        confronto per ogni due carte confrontate aggiunge uno al conteggio
        */
        function movesCounter() {
            // Aggiorna l'html per il contatore delle mosse
            movesCount.innerHTML ++;
            // Tiene traccia del numero di mosse per ogni coppia controllata
            moves ++;
        }

        /*
        Aggiorna la valutazione a stelle. A seconda del numero di
        mosse che l'utente completa nel gioco, le stelle diminuiranno
        con più mosse l'utente impiega.
        */
        // function starRating() {
        //     if (moves === 14) {
        //         // Il primo elemento figlio è l'<i> all'interno del <li>
        //         star[2].firstElementChild.classList.remove("fa-star");
        //         starCount--;
        //     }
        //     if (moves === 18) {
        //         star[1].firstElementChild.classList.remove("fa-star");
        //         starCount--;
        //     }
        // }

        /*
        Confronta due carte per vedere se corrispondono o meno
        */
        function compareTwo() {
            // Quando ci sono 2 carte nell'array opened
            if (opened.length === 2) {
                // Disabilita ulteriori click del mouse su altre carte
                document.body.style.pointerEvents = "none";
            }
            // Confronta il src delle due immagini
            if (opened.length === 2 && opened[0].src === opened[1].src) {
                // Se corrispondono chiama match()
                match();
                // console.log("È un Abbinamento!");
            } else if (opened.length === 2 && opened[0].src != opened[1].src) {
                // Se non corrispondono chiama noMatch()
                noMatch();
                // console.log("NESSUN Abbinamento!");
            }
        }

        /*
        Se le due carte corrispondono, mantieni le carte aperte e
        applica la classe match
        */
        function match() {

            /* Accede alle due carte nell'array opened e aggiunge
            la classe match al parent dell'immagine: il tag <li>
            */
            setTimeout(function() {
                opened[0].parentElement.classList.add("match");
                opened[1].parentElement.classList.add("match");
                // Inserisce le carte abbinate nell'array matched
                matched.push(...opened);
                // Permette ulteriori click del mouse sulle carte
                document.body.style.pointerEvents = "auto";
                // Controlla se il gioco è stato vinto con tutte le 8 coppie
                winGame();
                // Pulisce l'array opened
                opened = [];
            }, 600);
            // Chiama movesCounter per incrementare di uno
            movesCounter();




            //starRating();
        }

        /*
        Se le due carte non corrispondono, rimuove le carte
        dall'array opened e le gira di nuovo rimuovendo
        la classe flip.
        */
        function noMatch() {
            /* Dopo 700 millisecondi le due carte aperte avranno
            la classe flip rimossa dall'elemento padre dell'immagine <li>
            */
            setTimeout(function() {
                // Rimuove la classe flip sull'elemento padre dell'immagine
                opened[0].parentElement.classList.remove("flip");
                opened[1].parentElement.classList.remove("flip");
                // Permette ulteriori click del mouse sulle carte
                document.body.style.pointerEvents = "auto";
                // Rimuove le carte dall'array opened
                opened = [];
            }, 700);
            // Chiama movesCounter per incrementare di uno
            movesCounter();
            //starRating();
        }

        /*
        Ottiene le statistiche su tempo, numero di mosse e valutazione a stelle
        per la fine del gioco e aggiorna la modale con queste statistiche
        */
        function AddStats() {
            // Accede al div del contenuto della modale
            const stats = document.querySelector(".modal-content");

            timeStat.value="" + minutes + ":" + seconds;
            movesStat.value = moves;
        }


        function submitSection() {
            document.getElementById("section-form").submit();
        }   

        /*
        Controlla la lunghezza dell'array matched e se ci
        sono 8 coppie, 16 carte in totale, allora la partita è vinta.
        Ferma il timer, aggiorna la modale con le statistiche e mostra la modale
        */
        function winGame() {
            if (matched.length === 12) {
                stopTime();
                AddStats();

                submitSection();

                // displayModal();
            }

            matchedCount.innerHTML = matched.length/2 + " / " + 6;
        }

        /*----------------------------------
        Event Listener Principale
        ------------------------------------*/
        /*
        Event Listener se viene cliccato un <li> della carta
        chiama flipCard()
        */
        deck.addEventListener("click", function(evt) {
            if (evt.target.nodeName === "LI") {
                // Per verificare se stavo cliccando l'elemento corretto
                //console.log(evt.target.nodeName + " È stato cliccato");
                // Avvia il timer dopo il primo click su una carta
            // Esegue la funzione timer()
                if (timeStart === false) {
                    timeStart = true;
                    timer();
                }
                // Chiama la funzione flipCard()
                flipCard();
            }

            //Gira la carta e mostra l'immagine della carta
            function flipCard() {
                // Quando viene cliccato un <li> aggiunge la classe .flip per mostrare l'immagine
                evt.target.classList.add("flip");
                // Chiama la funzione addToOpened()
                addToOpened();
            }

            //Aggiunge le carte girate all'array vuoto opened
            function addToOpened() {
                /* Se l'array opened ha zero o un'altra immagine, inserisce un'altra
                immagine nell'array in modo da poter confrontare queste due per l'abbinamento
                */
                if (opened.length === 0 || opened.length === 1) {
                    // Inserisce quell'immagine nell'array opened
                    opened.push(evt.target.firstElementChild);
                }
                // Chiama la funzione compareTwo()
                compareTwo();
            }
        }); //Event Listener

        /*----------------------------------
        Pulsanti di Riavvio
        ------------------------------------*/
        /*
        Event Listener per ascoltare un click sul pulsante di reset,
        una volta cliccato chiama resetEverything()
        */
        reset.addEventListener('click', resetEverything);


    } // Fine della funzione initMemoryGame

    window.onload = initMemoryGame;

</script>

