public function castSet(mixed $value): mixed
{
    return match($this) {
        self::SELECT_MULTIPLE => json_encode($value),
        self::CHECKBOX => json_encode($value),
        self::CHECKBOX_IMAGE => json_encode($value),
        self::RADIO_TABLE => json_encode($value),
        self::RADIO_TABLE_TWO_COLS => json_encode($value),
        default => $value,
    };
}


/**
 * Cast the value for accessor.
 */
public function castGet(mixed $value): mixed
{
    return match($this) {
        self::SELECT_MULTIPLE => json_decode($value),
        self::CHECKBOX => json_decode($value),
        self::CHECKBOX_IMAGE => json_decode($value),
        self::RADIO_TABLE => json_decode($value, true),
        self::RADIO_TABLE_TWO_COLS => json_decode($value, true),

        // decode from base64
        // self::SIGNATURE => base64_decode($value),
        default => $value,
    };
}

/**
 * Get the answer processor (used in generation report) for this field type.
 * @return class-string|string
 */
public function getAnswerProcessor(): string
{
    return match($this) {
        self::SHORT_TEXT => ShortTextProcessor::class,

        // by default, convert the name to snake case and append Processor
        // e.g. LONG_TEXT => LongTextProcessor
        default => 'App\\Report\\AnswerProcessors\\'.Str::studly(strtolower($this->name)) . 'Processor',
    };
}
/**
 * Mutate the value to show as formatted answer.
 * E.g. for signature, show the image.
 * @param string $answer the answer value from database
 */
public function getAnswerAsFormattedString(?string $answer = null): string
{
    $returnValue = match($this) {
        self::SIGNATURE => '<img src="'.$answer.'" alt="Firma" style="max-width:200px;max-height:100px;"/>',
        self::TERMS => $answer == 'y' ? 'Accettato' : 'Non accettato',
        self::ACCEPTANCE => $answer == '1' ? 'Accettato' : 'Non accettato',
        self::IMAGE => $answer ? '
            <a href="'.Storage::disk('uploads')->url($answer).'" target="_blank" rel="noopener noreferrer">
                <img src="'.Storage::disk('uploads')->url($answer).'" alt="Foto" style="width:200px;height:200px;object-fit: contain;"/>
            </a>' : '-',
        self::BIRTH_DATE => $answer ? Carbon::parse($answer)->format('d/m/Y') : '-',
        default => $this->castGet($answer) ?? '-',
    };

    if (is_array($returnValue) || is_object($returnValue)) {
        $returnValue = json_encode($returnValue);
    }

    return $returnValue;
}

/**
 * Mutate the value to show in reports as question.
 */
public function parseReportQuestion(?string $questionText = null): ?string
{
    return match($this) {
        self::SIGNATURE => ($questionText ?? '') . ' [firma]',
        self::TERMS, self::ACCEPTANCE => ($questionText ?? '') . ' [accettazione]',
        default => $questionText,
    };
}


